class ImageComparator:
    def __init__(self):
        self.comparisons = []

    def compare(self, image_a: str, image_b: str, question: str) -> str:
        q = question.lower()
        if 'similar' in q:
            result = 'Images are similar.'
        elif 'differ' in q:
            result = 'Key differences: layout, color, content.'
        else:
            result = 'Comparison complete.'
        self.comparisons.append({
            "image_a": image_a,
            "image_b": image_b,
            "question": question,
            "result": result,
        })
        return result

    def summary(self) -> dict:
        images = set()
        for c in self.comparisons:
            images.add(c["image_a"])
            images.add(c["image_b"])
        return {
            "total_comparisons": len(self.comparisons),
            "unique_images": sorted(images),
            "questions": [c["question"] for c in self.comparisons],
        }


# Test it:
comp = ImageComparator()
r1 = comp.compare("before.jpg", "after.jpg", "What differences do you see?")
print(r1)

